  `role` varchar(10) NOT NULL DEFAULT 'ZONG' COMMENT 'ZONG=总龙头/FENZHI=分支龙/BUZHANG=补涨龙/FANBAO=反包龙(0.5/0.2/0.2/0.1)；兼容旧值 CYCLE/LEADER(按总龙)',
  `cycle_tag` varchar(20) DEFAULT NULL COMMENT '同轮归组标签，仅作显示分组',
  `start_date` date NOT NULL COMMENT '跨度起点：起爆日或人工认定的锚点日',
  `end_date` date DEFAULT NULL COMMENT '跨度终点，NULL 表示仍在位',
  `note` varchar(200) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_code_start` (`user_id`,`stock_code`,`start_date`),
  KEY `idx_user_span` (`user_id`,`start_date`,`end_date`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='周期阵眼与总龙头，第 8 维的来源';
