--

LOCK TABLES `t_daily_bar_fetch` WRITE;
/*!40000 ALTER TABLE `t_daily_bar_fetch` DISABLE KEYS */;
/*!40000 ALTER TABLE `t_daily_bar_fetch` ENABLE KEYS */;
