-- Table structure for table `t_industry_daily_snapshot`
--

DROP TABLE IF EXISTS `t_industry_daily_snapshot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_industry_daily_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trade_date` date NOT NULL COMMENT '交易日',
  `industry` varchar(20) NOT NULL COMMENT '行业板块(上游 hybk)',
  `zt_count` int NOT NULL DEFAULT '0' COMMENT '板块涨停家数',
  `max_board` int DEFAULT NULL COMMENT '板块最高连板数',
  `seal_sum` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '封单总额(元)',
  `yizi_cnt` int NOT NULL DEFAULT '0' COMMENT '一字板家数(首封<=9:30:00且未开板)',
  `big_loss_cnt` int NOT NULL DEFAULT '0' COMMENT '板块大面家数(炸板池 big_loss)',
  `tier_levels` varchar(64) DEFAULT '' COMMENT '覆盖层，逗号分隔的最高连板层如 "4,3,2"',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_date_industry` (`trade_date`,`industry`),
  KEY `idx_date_maxboard` (`trade_date`,`max_board`)
) ENGINE=InnoDB AUTO_INCREMENT=1280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='行业板块单日聚合快照(公开数据,T5)';
/*!40101 SET character_set_client = @saved_cs_client */;

