--
-- Table structure for table `t_market_stock`
--

DROP TABLE IF EXISTS `t_market_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_market_stock` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trade_date` date NOT NULL COMMENT '交易日',
  `code` varchar(6) NOT NULL COMMENT '6位代码',
  `name` varchar(20) NOT NULL COMMENT '证券简称',
  `pool` varchar(4) NOT NULL COMMENT 'ZT涨停/DT跌停/ZB炸板',
  `market` tinyint DEFAULT NULL COMMENT '东财标识：1=沪 0=深(含北)',
  `industry` varchar(20) DEFAULT '' COMMENT '行业板块(上游 hybk)',
  `consecutive` int DEFAULT NULL COMMENT '连板数 lbc(涨停池)',
  `break_count` int DEFAULT NULL COMMENT '炸板次数 zbc',
  `change_pct` decimal(6,2) DEFAULT NULL COMMENT '当日涨跌幅%',
  `close_price` decimal(12,3) DEFAULT NULL COMMENT '收盘价',
  `limit_price` decimal(12,3) DEFAULT NULL COMMENT '涨停/跌停价',
  `pullback_pct` decimal(6,2) DEFAULT NULL COMMENT '自涨停回撤%(炸板池)',
  `big_loss` tinyint DEFAULT '0' COMMENT '是否大面：回撤>7% 且收盘绿盘',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `seal_amount` decimal(18,2) DEFAULT NULL COMMENT '封单额(元)=东财fund,涨停池收盘封单资金',
  `first_seal_time` int DEFAULT NULL COMMENT '首次封板时间HHMMSS(fbt),判一字/T字用',
  `last_seal_time` int DEFAULT NULL COMMENT '最后封板时间HHMMSS(lbt)',
  `amount` decimal(18,2) DEFAULT NULL COMMENT '当日成交额(元)=东财池接口amount；D2成交额聚集度取数源(池内口径)',
  `float_mv` decimal(18,2) DEFAULT NULL COMMENT 'æµé€šå¸‚å€¼(å…ƒ)=ä¸œè´¢ltsz,ä»…æ¶¨åœæ± ï¼›ä¸€å­—æ–­é­‚åˆ€åˆ¤æ®(â‰¤20äº¿)',
  `turnover_rate` decimal(8,2) DEFAULT NULL COMMENT 'æ¢æ‰‹çŽ‡%=ä¸œè´¢hs,ä»…æ¶¨åœæ± ï¼›ä¸€å­—æ–­é­‚åˆ€åˆ¤æ®(<5%)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_date_code_pool` (`trade_date`,`code`,`pool`),
  KEY `idx_date_pool` (`trade_date`,`pool`),
  KEY `idx_date_bigloss` (`trade_date`,`big_loss`)
) ENGINE=InnoDB AUTO_INCREMENT=11452 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日盘面个股明细(公开数据,不绑用户)';
/*!40101 SET character_set_client = @saved_cs_client */;

