LOCK TABLES `t_node_detect` WRITE;
/*!40000 ALTER TABLE `t_node_detect` DISABLE KEYS */;
/*!40000 ALTER TABLE `t_node_detect` ENABLE KEYS */;
UNLOCK TABLES;

