  `avg_pct` decimal(7,2) DEFAULT NULL COMMENT '该档算术平均涨幅%',
  `max_pct` decimal(7,2) DEFAULT NULL,
  `min_pct` decimal(7,2) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_date_board` (`trade_date`,`board`),
  KEY `idx_date_group` (`trade_date`,`group_key`)
) ENGINE=InnoDB AUTO_INCREMENT=358 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='连板档位的昨日涨停今日溢价';
