DROP TABLE IF EXISTS `t_review_fetch`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_review_fetch` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trade_date` date NOT NULL COMMENT '拉取的交易日',
  `overall` varchar(12) NOT NULL DEFAULT 'PENDING' COMMENT 'RUNNING/DONE/PARTIAL/FAILED/PENDING',
  `tasks_json` varchar(2000) DEFAULT NULL COMMENT 'T1-T8 逐任务 {task,status,rows,msg} 的 JSON 数组',
  `warnings` varchar(1000) DEFAULT '' COMMENT '该日编排的汇总提示',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_date` (`trade_date`)
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日复盘一键拉取状态留档(T1-T8)';
/*!40101 SET character_set_client = @saved_cs_client */;

