--
-- Table structure for table `t_stock`
--

DROP TABLE IF EXISTS `t_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_stock` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(6) NOT NULL COMMENT '6位股票代码',
  `name` varchar(20) NOT NULL COMMENT '证券简称',
  `market` tinyint NOT NULL COMMENT '东财标识：1=沪 0=深(含北)',
  `board` varchar(10) NOT NULL COMMENT '沪主板/深主板/创业板/科创板/北交所',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `listed_at` date DEFAULT NULL COMMENT '上市日期，次新股过滤(filter_new_stock_days)用；NULL=未知，该股不因新股被剔',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5917 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='A股代码名称总表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `t_stock`
--

LOCK TABLES `t_stock` WRITE;
/*!40000 ALTER TABLE `t_stock` DISABLE KEYS */;
